import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Autocomplete,
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  Radio,
  RadioGroup,
  TextField,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import { CleaveNumberInput } from "src/@core/components/cleave-components";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";

const validationSchema = yup.object().shape({
  title: yup.string().trim().required("Title is required"),
  email: yup
    .string()
    .trim()
    .email("Enter valid email")
    .required("Email is required"),
  description: yup.string().trim().required("Description is required"),
  time: yup
    .string()
    .trim()
    .required("Time is required")
    .matches(
      /^([01]\d|2[0-3]):([0-5]\d)$|^([1-9]|1[0-2]) ?(AM|PM|am|pm) ?(?:- ?([1-9]|1[0-2]) ?(AM|PM|am|pm))?$/,
      "Time must be in HH:mm or X AM/PM - Y AM/PM format"
    ),
});

const DialogContact = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess } = props;

  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");

  const {
    control,
    handleSubmit,
    reset,
    setValue,
    formState: { errors },
  } = useForm({
    defaultValues: {
      title: "",
      email: "",
      description: "",
      time: "",
      status: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  useEffect(() => {
    if (open) {
      setLoading(false);

      setDialogTitle(
        mode === "add" ? "Add Contact Details " : "Edit Contact Details"
      );
      reset({
        title: dataToEdit?.title || "",
        email: dataToEdit?.email || "",
        description: dataToEdit?.description || "",
        time: dataToEdit?.time || "",
        status: dataToEdit?.status || "active",
      });
    }
  }, [dataToEdit, mode, open, reset]);

  const onSubmit = (data) => {
    let payload = {
      title: data.title,
      email: data.email,
      description: data.description,
      time: data.time,
    };
    if (mode === "edit") {
      payload.status = data.status;
    }
    setLoading(true);

    let apiInstance = null;

    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.ContactUs.edit(dataToEdit.id),
        payload
      );
    } else {
      apiInstance = axiosInstance.post(ApiEndPoints.ContactUs.create, payload);
    }
    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  return (
    <>
      <Dialog open={open} fullWidth maxWidth="sm" scroll="paper">
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          {dialogTitle}
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="hub-address-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={4}>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel htmlFor="title" error={Boolean(errors.title)}>
                    Title
                  </FormLabel>
                  <Controller
                    name="title"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        // disabled
                        placeholder="Enter Title"
                        multiline
                        autoFocus
                        onChange={onChange}
                        id="title"
                        value={value}
                        error={Boolean(errors.title)}
                      />
                    )}
                  />
                  {errors.title && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.title.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={6}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel htmlFor="time" error={Boolean(errors.time)}>
                    Time
                  </FormLabel>
                  <Controller
                    name="time"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Time"
                        multiline
                        autoFocus
                        onChange={onChange}
                        id="time"
                        value={value}
                        error={Boolean(errors.time)}
                      />
                    )}
                  />
                  {errors.time && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.time.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>
              <Grid item xs={6}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel htmlFor="email" error={Boolean(errors.email)}>
                    Email
                  </FormLabel>
                  <Controller
                    name="email"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder="Enter Email"
                        multiline
                        autoFocus
                        onChange={onChange}
                        id="email"
                        value={value}
                        error={Boolean(errors.email)}
                      />
                    )}
                  />
                  {errors.email && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.email.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>

              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    htmlFor="description"
                    error={Boolean(errors.description)}
                  >
                    Description
                  </FormLabel>
                  <Controller
                    name="description"
                    control={control}
                    render={({ field }) => (
                      <ReactQuill
                        theme="snow"
                        {...field}
                        modules={{
                          toolbar: [
                            [{ header: [1, 2, 3, 4, 5, 6, false] }],
                            ["bold", "italic", "underline", "strike"],
                            ["blockquote", "code-block"],
                            [{ list: "ordered" }, { list: "bullet" }],
                            [{ script: "sub" }, { script: "super" }],
                            [{ indent: "-1" }, { indent: "+1" }],
                            [{ direction: "rtl" }],
                            [{ size: ["small", false, "large", "huge"] }],
                            [{ color: [] }, { background: [] }],
                            [{ font: [] }],
                            ["link"],
                            ["clean"],
                          ],
                        }}
                        formats={[
                          "header",
                          "font",
                          "size",
                          "bold",
                          "italic",
                          "underline",
                          "strike",
                          "blockquote",
                          "list",
                          "bullet",
                          "indent",
                          "script",
                          "link",
                          "color",
                          "background",
                        ]}
                        onChange={(value) => {
                          setValue("description", value, {
                            shouldValidate: true,
                          });
                          field.onChange(value);
                        }}
                      />
                    )}
                  />
                  {errors.description && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.description.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>

              {mode === "edit" && (
                <Grid item xs={12}>
                  <FormControl fullWidth>
                    <FormLabel htmlFor="status" error={Boolean(errors.status)}>
                      Status
                    </FormLabel>
                    <Controller
                      name="status"
                      control={control}
                      render={({ field: { value, onChange } }) => (
                        <RadioGroup
                          row
                          name="status"
                          onChange={onChange}
                          value={value}
                        >
                          <FormControlLabel
                            value={"active"}
                            control={<Radio />}
                            label="Active"
                          />
                          <FormControlLabel
                            value={"inactive"}
                            control={<Radio />}
                            label="Inactive"
                          />
                        </RadioGroup>
                      )}
                    />
                    {errors.status && (
                      <FormHelperText sx={{ color: "error.main" }}>
                        {errors.status.message}
                      </FormHelperText>
                    )}
                  </FormControl>
                </Grid>
              )}
            </Grid>
          </form>
        </DialogContent>

        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="hub-address-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
        {/* )} */}
      </Dialog>
    </>
  );
};

export default DialogContact;
